(()=>{
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY={sessions:'rh_ypt_sessions',claimed:'rh_ypt_claimedAvatars',selected:'rh_ypt_selectedAvatar',theme:'rh_ypt_amoled'};
const AVATARS=[
 {id:'rookie-boy',hours:0,name:'Focus Rookie',gender:'boys',tag:'STARTER'},
 {id:'rookie-girl',hours:0,name:'Study Spark',gender:'girls',tag:'STARTER'},
 {id:'scholar-boy',hours:5,name:'NEET Scholar',gender:'boys',tag:'5 HOURS'},
 {id:'scholar-girl',hours:5,name:'Note Princess',gender:'girls',tag:'5 HOURS'},
 {id:'focus-artist-boy',hours:5,name:'Focus Artist',gender:'boys',tag:'5 HOURS'},
 {id:'star-student-girl',hours:5,name:'Star Student',gender:'girls',tag:'5 HOURS'},
 {id:'bio-boy',hours:10,name:'Bio Guardian',gender:'boys',tag:'10 HOURS'},
 {id:'bio-girl',hours:10,name:'Forest Healer',gender:'girls',tag:'10 HOURS'},
 {id:'mind-ninja-boy',hours:10,name:'Mind Ninja',gender:'boys',tag:'10 HOURS'},
 {id:'knowledge-bloom-girl',hours:10,name:'Knowledge Bloom',gender:'girls',tag:'10 HOURS'},
 {id:'phoenix-boy',hours:20,name:'Focus Phoenix',gender:'boys',tag:'20 HOURS'},
 {id:'phoenix-girl',hours:20,name:'Flame Oracle',gender:'girls',tag:'20 HOURS'},
 {id:'ember-mentor-boy',hours:20,name:'Ember Mentor',gender:'boys',tag:'20 HOURS'},
 {id:'forest-muse-girl',hours:20,name:'Forest Muse',gender:'girls',tag:'20 HOURS'},
 {id:'knight-boy',hours:35,name:'NEET Knight',gender:'boys',tag:'35 HOURS'},
 {id:'knight-girl',hours:35,name:'Royal Mentor',gender:'girls',tag:'35 HOURS'},
 {id:'zen-strategist-boy',hours:35,name:'Zen Strategist',gender:'boys',tag:'35 HOURS'},
 {id:'legend-boy',hours:50,name:'Rathod Legend',gender:'boys',tag:'50 HOURS'},
 {id:'legend-girl',hours:50,name:'Rathod Empress',gender:'girls',tag:'50 HOURS'},
 {id:'galaxy-muse-girl',hours:50,name:'Galaxy Muse',gender:'girls',tag:'50 HOURS'}
];
const AVATAR_ART=Object.freeze({
 'rookie-boy':'data:image/webp;base64,',
 'rookie-girl':'data:image/webp;base64,',
 'scholar-boy':'data:image/webp;base64,',
 'scholar-girl':'data:image/webp;base64,',
 'knight-boy':'data:image/webp;base64,',
 'knight-girl':'data:image/webp;base64,',
 'phoenix-boy':'data:image/webp;base64,',
 'phoenix-girl':'data:image/webp;base64,',
 'legend-girl':'data:image/webp;base64,',
 'legend-boy':'data:image/webp;base64,',
 'bio-girl':'data:image/webp;base64,',
 'bio-boy':'data:image/webp;base64,',
 'ember-mentor-boy':'data:image/webp;base64,',
 'forest-muse-girl':'data:image/webp;base64,',
 'mind-ninja-boy':'data:image/webp;base64,',
 'knowledge-bloom-girl':'data:image/webp;base64,',
 'focus-artist-boy':'data:image/webp;base64,',
 'star-student-girl':'data:image/webp;base64,',
 'zen-strategist-boy':'data:image/webp;base64,',
 'galaxy-muse-girl':'data:image/webp;base64,'
});
const LEGACY={starter:'rookie-boy',scholar:'scholar-boy',botanist:'bio-boy',phoenix:'phoenix-boy',knight:'knight-boy',legend:'legend-boy'};
let filter='all',installPrompt=window.__rathodInstallPrompt||null;
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
const write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
function weekStart(){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return d}
function weeklySeconds(){const start=weekStart();return read(KEY.sessions,[]).filter(x=>new Date(x.started_at||x.date)>=start).reduce((n,x)=>n+Number(x.seconds||x.duration_seconds||0),0)}
function format(sec){const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60);return `${h}h ${m}m`}
function claimed(){const old=read(KEY.claimed,['starter']);const mapped=old.map(x=>LEGACY[x]||x);if(!mapped.includes('rookie-boy'))mapped.push('rookie-boy');if(!mapped.includes('rookie-girl'))mapped.push('rookie-girl');return new Set(mapped)}
function selected(){const id=read(KEY.selected,'rookie-boy');return LEGACY[id]||id}
function avatar(id){return AVATARS.find(x=>x.id===id)||AVATARS[0]}
function avatarSvg(a){return AVATAR_ART[a.id]||AVATAR_ART['rookie-boy']}
function ensureTabs(){const grid=$('#avatarRewardGrid');if(!grid||$('#avatarRewardTabs'))return;const tabs=document.createElement('div');tabs.id='avatarRewardTabs';tabs.className='avatar-reward-tabs';tabs.innerHTML='<button class="active" data-avatar-filter="all">All</button><button data-avatar-filter="girls">👧 Girls</button><button data-avatar-filter="boys">👦 Boys</button>';grid.before(tabs);tabs.onclick=e=>{const b=e.target.closest('[data-avatar-filter]');if(!b)return;filter=b.dataset.avatarFilter;$$('[data-avatar-filter]').forEach(x=>x.classList.toggle('active',x===b));render()}}
function render(){const grid=$('#avatarRewardGrid');if(!grid)return;ensureTabs();const sec=weeklySeconds(),hours=sec/3600,owned=claimed(),current=avatar(selected()),nextHours=[5,10,20,35,50].find(h=>h>hours);$('#rewardHours').textContent=format(sec);$('#rewardHeroAvatar').className='reward-hero-avatar';$('#rewardHeroAvatar').innerHTML=`<img src="${avatarSvg(current)}" alt="${current.name}">`;$('#rewardNextText').textContent=nextHours?`${nextHours} hours reward के लिए ${Math.max(0,nextHours-hours).toFixed(1)} hours और`:'इस हफ्ते का Legend level complete 👑';$('#rewardProgressBar').style.width=`${nextHours?Math.min(100,hours/nextHours*100):100}%`;const shown=AVATARS.filter(a=>filter==='all'||a.gender===filter);grid.innerHTML=shown.map(a=>{const isOwned=owned.has(a.id),ready=hours>=a.hours,isSelected=a.id===current.id;return `<article class="avatar-reward-card ${isOwned?'owned':''} ${ready?'ready':''}"><span class="avatar-tag">${a.tag} · ${a.gender==='girls'?'GIRL':'BOY'}</span><div class="avatar-3d"><img src="${avatarSvg(a)}" alt="${a.name}">${!ready&&!isOwned?'<span class="avatar-lock">🔒</span>':''}</div><h3>${a.name}</h3><p>${a.hours?a.hours+' weekly focus hours':'Free starter avatar'}</p><button data-avatar-action="${a.id}" ${!ready&&!isOwned?'disabled':''}>${isSelected?'✓ Equipped':isOwned?'Use avatar':ready?'Claim free':'Keep studying'}</button></article>`}).join('');applyAvatar(current)}
function act(id){const a=avatar(id),sec=weeklySeconds(),owned=claimed();if(!owned.has(id)){if(sec<a.hours*3600)return toast('अभी weekly hours पूरे नहीं हुए');owned.add(id);write(KEY.claimed,[...owned]);toast(`${a.name} permanently claimed 🎉`)}write(KEY.selected,id);render()}
function applyAvatar(a){const top=$('#topAvatar');if(!top)return;top.classList.add('has-reward-avatar');top.innerHTML=`<img class="profile-anime-avatar" src="${avatarSvg(a)}" alt="${a.name}">`;top.title=a.name}
function toast(text){const t=$('#toast');if(!t)return; t.textContent=text;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2600)}
function setTheme(on){document.body.classList.toggle('amoled',on);write(KEY.theme,on);const b=$('#themeToggle');if(b)b.textContent=on?'☀ Use premium dark':'● Use AMOLED black'}
function setOnline(){const b=$('#networkBadge');if(!b)return;b.textContent=navigator.onLine?'● ONLINE':'● OFFLINE READY';b.classList.toggle('offline',!navigator.onLine)}
function boot(){setTheme(read(KEY.theme,false));setOnline();render();window.addEventListener('rathod-install-ready',e=>{installPrompt=e.detail||window.__rathodInstallPrompt;$('#installAppBtn')?.classList.remove('hidden')});window.addEventListener('online',()=>{setOnline();toast('Back online · pending data will sync')});window.addEventListener('offline',()=>{setOnline();toast('Offline mode · timer safe रहेगा')});$('#themeToggle')?.addEventListener('click',()=>setTheme(!document.body.classList.contains('amoled')));document.addEventListener('click',e=>{const b=e.target.closest('[data-avatar-action]');if(b)act(b.dataset.avatarAction)});setInterval(render,30000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
